// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListUsers All users (admin)
	// (GET /api/v1/admin/users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// CreateUser Create a user with a password login (admin)
	// (POST /api/v1/admin/users)
	CreateUser(ctx context.Context, request CreateUserRequestObject) (CreateUserResponseObject, error)
	// GetUser One user (admin, or the user themself; job serves GET /api/v1/me)
	// (GET /api/v1/admin/users/{userId})
	GetUser(ctx context.Context, request GetUserRequestObject) (GetUserResponseObject, error)
	// UpdateUser Change role and/or status (admin); the last active admin is protected
	// (PATCH /api/v1/admin/users/{userId})
	UpdateUser(ctx context.Context, request UpdateUserRequestObject) (UpdateUserResponseObject, error)
	// UnlinkOIDCIdentity Remove the user's OIDC identity (admin); a user without a password keeps it
	// (DELETE /api/v1/admin/users/{userId}/oidc-identity)
	UnlinkOIDCIdentity(ctx context.Context, request UnlinkOIDCIdentityRequestObject) (UnlinkOIDCIdentityResponseObject, error)
	// LinkOIDCIdentity Link the user to an OIDC identity (admin, DEC-04)
	// (PUT /api/v1/admin/users/{userId}/oidc-identity)
	LinkOIDCIdentity(ctx context.Context, request LinkOIDCIdentityRequestObject) (LinkOIDCIdentityResponseObject, error)
	// ResetUserPassword Set a new password for a user and revoke their sessions (admin)
	// (PUT /api/v1/admin/users/{userId}/password)
	ResetUserPassword(ctx context.Context, request ResetUserPasswordRequestObject) (ResetUserPasswordResponseObject, error)
	// LogIn Log in with username and password
	// (POST /api/v1/auth/login)
	LogIn(ctx context.Context, request LogInRequestObject) (LogInResponseObject, error)
	// LogOut Revoke the current session
	// (POST /api/v1/auth/logout)
	LogOut(ctx context.Context, request LogOutRequestObject) (LogOutResponseObject, error)
	// FinishOIDCLogin The provider's redirect back; logs in a pre-linked user (DEC-04)
	// (GET /api/v1/auth/oidc/callback)
	FinishOIDCLogin(ctx context.Context, request FinishOIDCLoginRequestObject) (FinishOIDCLoginResponseObject, error)
	// StartOIDCLogin Redirect to the OIDC provider (authorization code with PKCE, DEC-04)
	// (GET /api/v1/auth/oidc/login)
	StartOIDCLogin(ctx context.Context, request StartOIDCLoginRequestObject) (StartOIDCLoginResponseObject, error)
	// ChangeOwnPassword Change the own password; other sessions are revoked
	// (PUT /api/v1/me/password)
	ChangeOwnPassword(ctx context.Context, request ChangeOwnPasswordRequestObject) (ChangeOwnPasswordResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListUsers operation middleware
func (sh *strictHandler) ListUsers(w http.ResponseWriter, r *http.Request) {
	var request ListUsersRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListUsers(ctx, request.(ListUsersRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListUsers")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListUsersResponseObject); ok {
		if err := validResponse.VisitListUsersResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

